                            if g[rr][cc] == 0:
                                additions.add((rr,cc))
        else:
            # Vertical beam, with identical 3x3 illumination at horizontal dividers.
            for i in range(h):
                if g[i][c] == 0:
                    additions.add((i,c))
            for i in range(h):
                if i != r and g[i][c] == 2:
                    for rr in range(max(0,i-1), min(h,i+2)):
                        for cc in range(max(0,c-1), min(w,c+2)):
                            if g[rr][cc] == 0:
                                additions.add((rr,cc))
    for r,c in additions:
        g[r][c] = 1
    return g
